void KeyframeEffect::UpdateProperties(const ComputedStyle* aStyle,
                                      const AnimationTimeline* aTimeline) {
  MOZ_ASSERT(aStyle);

  nsTArray<AnimationProperty> properties = BuildProperties(
      aStyle, aTimeline ? aTimeline
                        : (mAnimation ? mAnimation->GetTimeline() : nullptr));

  bool propertiesChanged = mProperties != properties;
  if (!propertiesChanged) {
    auto attrTainted = [](const AnimationValue& aValue) {
      return aValue.mServo && Servo_AnimationValue_IsAttrTainted(aValue.mServo);
    };
    for (size_t i = 0; i < properties.Length() && !propertiesChanged; ++i) {
      if (!properties[i].mProperty.IsCustom()) {
        continue;
      }
      const auto& oldSegments = mProperties[i].mSegments;
      const auto& newSegments = properties[i].mSegments;
      for (size_t j = 0; j < newSegments.Length(); ++j) {
        const auto& oldSegment = oldSegments[j];
        const auto& newSegment = newSegments[j];
        if (attrTainted(oldSegment.mFromValue) !=
                attrTainted(newSegment.mFromValue) ||
            attrTainted(oldSegment.mToValue) != attrTainted(newSegment.mToValue)) {
          propertiesChanged = true;
          break;
        }
      }
    }
  }

  // We need to update base styles even if any properties are not changed at all
  // since base styles might have been changed due to parent style changes, etc.
  bool baseStylesChanged = false;
  EnsureBaseStyles(aStyle, properties, aTimeline,
                   !propertiesChanged ? &baseStylesChanged : nullptr);

  if (!propertiesChanged) {
    if (baseStylesChanged) {
      RequestRestyle(EffectCompositor::RestyleType::Layer);
    }
    return;
  }

  // Preserve the state of the mIsRunningOnCompositor flag.
  nsCSSPropertyIDSet runningOnCompositorProperties;

  for (const AnimationProperty& property : mProperties) {
    if (property.mIsRunningOnCompositor) {
      runningOnCompositorProperties.AddProperty(property.mProperty.mId);
    }
  }

  mProperties = std::move(properties);
  UpdateEffectSet();

  mCumulativeChanges = {};
  for (AnimationProperty& property : mProperties) {
    property.mIsRunningOnCompositor =
        runningOnCompositorProperties.HasProperty(property.mProperty);
    CalculateCumulativeChangesForProperty(property);
  }

  MarkCascadeNeedsUpdate();

  if (mAnimation) {
    mAnimation->NotifyEffectPropertiesUpdated();
  }

  RequestRestyle(EffectCompositor::RestyleType::Layer);
}

void KeyframeEffect::EnsureBaseStyles(
    const ComputedStyle* aComputedValues,
    const nsTArray<AnimationProperty>& aProperties,
    const AnimationTimeline* aTimeline, bool* aBaseStylesChanged) {
  if (aBaseStylesChanged != nullptr) {
    *aBaseStylesChanged = false;
  }

  if (!mTarget) {
    return;
  }

  BaseValuesHashmap previousBaseStyles;
  if (aBaseStylesChanged != nullptr) {
    previousBaseStyles = std::move(mBaseValues);
  }

  mBaseValues.Clear();

  nsPresContext* presContext =
      nsContentUtils::GetContextForContent(mTarget.mElement);
  // If |aProperties| is empty we're not going to dereference |presContext| so
  // we don't care if it is nullptr.
  //
  // We could just return early when |aProperties| is empty and save looking up
  // the pres context, but that won't save any effort normally since we don't
  // call this function if we have no keyframes to begin with. Furthermore, the
  // case where |presContext| is nullptr is so rare (we've only ever seen in
  // fuzzing, and even then we've never been able to reproduce it reliably)
  // it's not worth the runtime cost of an extra branch.
  MOZ_ASSERT(presContext || aProperties.IsEmpty(),
             "Typically presContext should not be nullptr but if it is"
             " we should have also failed to calculate the computed values"
             " passed-in as aProperties");

  if (!aTimeline) {
    // If we pass a valid timeline, we use it (note: this happens when we create
    // a new animation or replace the old one, for CSS Animations and CSS
    // Transitions). Otherwise, we check the timeline from |mAnimation|.
    aTimeline = mAnimation ? mAnimation->GetTimeline() : nullptr;
  }

  RefPtr<const ComputedStyle> baseComputedStyle;
  for (const AnimationProperty& property : aProperties) {
    EnsureBaseStyle(property, presContext, aComputedValues, aTimeline,
                    baseComputedStyle);
  }

  if (aBaseStylesChanged != nullptr &&
      std::any_of(
          mBaseValues.cbegin(), mBaseValues.cend(), [&](const auto& entry) {
            return AnimationValue(entry.GetData()) !=
                   AnimationValue(previousBaseStyles.Get(entry.GetKey()));
          })) {
    *aBaseStylesChanged = true;
  }
}

void KeyframeEffect::SetKeyframes(nsTArray<Keyframe>&& aKeyframes,
                                  const ComputedStyle* aStyle,
                                  const AnimationTimeline* aTimeline,
                                  const AnimationRange* aRange) {
  if (KeyframesEqualIgnoringComputedOffsets(aKeyframes, mKeyframes)) {
    return;
  }

  mKeyframes = std::move(aKeyframes);
  mKeyframeOffsetsHasRangeOffset = KeyframeUtils::ComputeMissingKeyframeOffsets(
      mKeyframes, aTimeline, aRange);

  if (mAnimation && mAnimation->IsRelevant()) {
    MutationObservers::NotifyAnimationChanged(mAnimation);
  }

  // We need to call UpdateProperties() unless the target element doesn't have
  // style (e.g. the target element is not associated with any document).
  if (aStyle) {
    UpdateProperties(aStyle, aTimeline);
  }
}

nsTArray<AnimationProperty> KeyframeEffect::BuildProperties(
    const ComputedStyle* aStyle, const AnimationTimeline* aTimeline) {
  MOZ_ASSERT(aStyle);

  nsTArray<AnimationProperty> result;
  // If mTarget is false (i.e. mTarget.mElement is null), return an empty
  // property array.
  if (!mTarget) {
    return result;
  }

  // When GetComputedKeyframeValues or GetAnimationPropertiesFromKeyframes
  // calculate computed values from |mKeyframes|, they could possibly
  // trigger a subsequent restyle in which we rebuild animations. If that
  // happens we could find that |mKeyframes| is overwritten while it is
  // being iterated over. Normally that shouldn't happen but just in case we
  // make a copy of |mKeyframes| first and iterate over that instead.
  auto keyframesCopy(mKeyframes.Clone());

  // We generate the missing 0%/100% keyframes and append the missing
  // properties to 0%/100% only if the keyframes come from CSS Keyframes rule.
  // Note: We probably can avoid an extra copy above if GetComputedKeyframes()
  // return true. However, we use the same function in GetKeyframes() so for
  // readibility we still keep it as it is. If this result in any performance
  // impact, we should write a special version of GetComputedKeyframes() here.
  nsTArray<Keyframe> computedKeyframes;
  const nsTArray<Keyframe>& keyframes = GetComputedKeyframes(computedKeyframes)
                                            ? computedKeyframes
                                            : keyframesCopy;

  result = KeyframeUtils::GetAnimationPropertiesFromKeyframes(
      keyframes, mTarget.mElement, mTarget.mPseudoRequest, aStyle,
      mEffectOptions.mComposite, aTimeline);

#ifdef DEBUG
  MOZ_ASSERT(SpecifiedKeyframeArraysAreEqual(mKeyframes, keyframesCopy),
             "Apart from the computed offset members, the keyframes array"
             " should not be modified");
#endif

  mKeyframes = std::move(keyframesCopy);
  return result;
}

void KeyframeEffect::UpdateProperties(const ComputedStyle* aStyle,
                                      const AnimationTimeline* aTimeline) {
  MOZ_ASSERT(aStyle);

  nsTArray<AnimationProperty> properties = BuildProperties(
      aStyle, aTimeline ? aTimeline
                        : (mAnimation ? mAnimation->GetTimeline() : nullptr));

  bool propertiesChanged = mProperties != properties;

  // We need to update base styles even if any properties are not changed at all
  // since base styles might have been changed due to parent style changes, etc.
  bool baseStylesChanged = false;
  EnsureBaseStyles(aStyle, properties, aTimeline,
                   !propertiesChanged ? &baseStylesChanged : nullptr);

  if (!propertiesChanged) {
    if (baseStylesChanged) {
      RequestRestyle(EffectCompositor::RestyleType::Layer);
    }
    return;
  }

  // Preserve the state of the mIsRunningOnCompositor flag.
  nsCSSPropertyIDSet runningOnCompositorProperties;

  for (const AnimationProperty& property : mProperties) {
    if (property.mIsRunningOnCompositor) {
      runningOnCompositorProperties.AddProperty(property.mProperty.mId);
    }
  }

  mProperties = std::move(properties);
  UpdateEffectSet();

  mCumulativeChanges = {};
  for (AnimationProperty& property : mProperties) {
    property.mIsRunningOnCompositor =
        runningOnCompositorProperties.HasProperty(property.mProperty);
    CalculateCumulativeChangesForProperty(property);
  }

  MarkCascadeNeedsUpdate();

  if (mAnimation) {
    mAnimation->NotifyEffectPropertiesUpdated();
  }

  RequestRestyle(EffectCompositor::RestyleType::Layer);
}

pub fn is_attr_tainted(&self) -> bool {
        self.value.as_ref().is_some_and(|value| value.attr_tainted)
    }

pub fn from_computed(
        name: &crate::custom_properties::Name,
        value: Option<&ComputedValue>,
    ) -> Self {
        Self {
            name: name.clone(),
            value: value.cloned(),
        }
    }

pub(crate) fn from_declaration(
        declaration: &properties::CustomDeclaration,
        context: &mut computed::Context,
    ) -> Option<Self> {
        let computed_value = match declaration.value {
            properties::CustomDeclarationValue::Unparsed(ref value) => Some({
                debug_assert!(
                    context.builder.stylist.is_some(),
                    "Need a Stylist to get property registration!"
                );
                let registration = context
                    .builder
                    .stylist
                    .unwrap()
                    .get_custom_property_registration(&declaration.name);
                if registration.is_universal() {
                    // FIXME: Do we need to perform substitution here somehow?
                    ComputedValue::universal(Arc::clone(value))
                } else {
                    let mut input = CSSParser::new(&value.css);
                    SpecifiedValue::compute(
                        &mut input,
                        registration,
                        None,
                        &value.url_data,
                        context,
                        AllowComputationallyDependent::Yes,
                        /* attr_taint */ Default::default(),
                        Some(PropertyIdRef::from(&declaration.name)),
                    )
                    .unwrap_or_else(|_| ComputedValue::universal(Arc::clone(value)))
                }
            }),
            properties::CustomDeclarationValue::Parsed(ref v) => Some(v.to_computed_value(context)),
            properties::CustomDeclarationValue::CSSWideKeyword(keyword) => {
                let stylist = context.builder.stylist.unwrap();
                let registration = stylist.get_custom_property_registration(&declaration.name);
                match keyword {
                    CSSWideKeyword::Initial => stylist
                        .get_custom_property_initial_values()
                        .get(registration, &declaration.name),
                    CSSWideKeyword::Inherit => context
                        .builder
                        .inherited_custom_properties()
                        .get(registration, &declaration.name),
                    CSSWideKeyword::Unset => {
                        if registration.inherits() {
                            context
                                .builder
                                .inherited_custom_properties()
                                .get(registration, &declaration.name)
                        } else {
                            stylist
                                .get_custom_property_initial_values()
                                .get(registration, &declaration.name)
                        }
                    },
                    // FIXME(emilio, bug 1533327): I think revert (and
                    // revert-layer) handling is not fine here, but what to
                    // do instead?
                    //
                    // Seems we'd need the computed value as if it was
                    // revert, somehow. Returning `None` seems fine for now...
                    //
                    // Note that once this is fixed, this method should be
                    // able to return `Self` instead of Option<Self>`.
                    CSSWideKeyword::Revert
                    | CSSWideKeyword::RevertRule
                    | CSSWideKeyword::RevertLayer => return None,
                }
                .cloned()
            },
        };
        Some(Self {
            name: declaration.name.clone(),
            value: computed_value,
        })
    }

pub(crate) fn to_declaration(&self) -> properties::PropertyDeclaration {
        properties::PropertyDeclaration::Custom(properties::CustomDeclaration {
            name: self.name.clone(),
            value: match &self.value {
                Some(value) => value.to_declared_value(),
                None => CustomDeclarationValue::CSSWideKeyword(CSSWideKeyword::Initial),
            },
        })
    }

pub struct CustomAnimatedValue {
    /// The name of the custom property.
    pub(crate) name: crate::custom_properties::Name,
    /// The computed value of the custom property.
    /// `None` represents the guaranteed-invalid value.
    pub(crate) value: Option<ComputedValue>,
}

impl<Component: PartialEq> PartialEq for Value<Component> {
    // Ignore the url_data and tainting fields when comparing values for equality.
    fn eq(&self, other: &Self) -> bool {
        self.v == other.v
    }
}

pub extern "C" fn Servo_AnimationValue_DeepEqual(
    this: &AnimationValue,
    other: &AnimationValue,
) -> bool {
    this == other
}

pub extern "C" fn Servo_AnimationValue_IsAttrTainted(value: &AnimationValue) -> bool {
    match value {
        AnimationValue::Custom(value) => value.is_attr_tainted(),
        _ => false,
    }
}

bool operator==(const AnimationPropertySegment& aOther) const {
    return mFromKey == aOther.mFromKey && mToKey == aOther.mToKey &&
           mFromValue == aOther.mFromValue && mToValue == aOther.mToValue &&
           mTimingFunction == aOther.mTimingFunction &&
           mFromComposite == aOther.mFromComposite &&
           mToComposite == aOther.mToComposite;
  }

bool operator==(const AnimationProperty& aOther) const {
    return mProperty == aOther.mProperty && mSegments == aOther.mSegments;
  }

bool AnimationValue::operator==(const AnimationValue& aOther) const {
  if (mServo && aOther.mServo) {
    return Servo_AnimationValue_DeepEqual(mServo, aOther.mServo);
  }
  if (!mServo && !aOther.mServo) {
    return true;
  }
  return false;
}
